import { test, expect } from '@playwright/test';

test.describe('Sticky Header Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/navigation');
  });

  test('should display sticky header when scrolling down', async ({ page }) => {
    // Verify header is visible initially
    const header = page.getByRole('banner');
    await expect(header).toBeVisible();

    // Verify logo is visible
    const logo = page.getByRole('img', { name: /logo/i });
    await expect(logo).toBeVisible();

    // Verify navigation links are visible
    const navLinks = page.getByRole('navigation').getByText(/home|about|contact/i);
    await expect(navLinks).toBeVisible();

    // Scroll down to trigger sticky behavior
    await page.evaluate(() => window.scrollTo(0, 800));

    // Verify header remains visible and sticky
    await expect(header).toBeVisible();

    // Verify header has sticky class
    const headerElement = page.locator('[data-testid="sticky-header"]');
    await expect(headerElement).toHaveClass(/sticky-header/);

    // Verify header position is fixed
    const headerBoundingBox = await headerElement.boundingBox();
    expect(headerBoundingBox.y).toBeLessThan(100);

    // Verify logo is still visible in sticky header
    await expect(logo).toBeVisible();

    // Verify navigation links are still visible in sticky header
    await expect(navLinks).toBeVisible();
  });

  test('should not become sticky when scrolling up', async ({ page }) => {
    // Scroll down to trigger sticky header
    await page.evaluate(() => window.scrollTo(0, 800));

    // Verify header is sticky
    const headerElement = page.locator('[data-testid="sticky-header"]');
    await expect(headerElement).toHaveClass(/sticky-header/);

    // Scroll back up
    await page.evaluate(() => window.scrollTo(0, 0));

    // Verify header remains sticky
    await expect(headerElement).toHaveClass(/sticky-header/);

    // Verify header position is fixed
    const headerBoundingBox = await headerElement.boundingBox();
    expect(headerBoundingBox.y).toBeLessThan(100);

    // Verify logo is still visible
    const logo = page.getByRole('img', { name: /logo/i });
    await expect(logo).toBeVisible();

    // Verify navigation links are still visible
    const navLinks = page.getByRole('navigation').getByText(/home|about|contact/i);
    await expect(navLinks).toBeVisible();
  });
});
